import dayjs from 'dayjs';

/**
 * Gets the number of days in a specific month
 */
export const getDaysInMonth = (year, month) => {
  return new Date(year, month + 1, 0).getDate();
};

/**
 * Gets the day of week for the first day of a month (0 = Sunday, 6 = Saturday)
 */
export const getFirstDayOfMonth = (year, month) => {
  return new Date(year, month, 1).getDay();
};

/**
 * Formats a date as YYYY-MM-DD
 */
export const formatDate = (year, month, day) => {
  const paddedMonth = String(month + 1).padStart(2, '0');
  const paddedDay = String(day).padStart(2, '0');
  return `${year}-${paddedMonth}-${paddedDay}`;
};

/**
 * Formats a date for display
 */
export const formatDateForDisplay = (dateString) => {
  if (!dateString) return '';

  try {
    const date = dayjs(dateString);
    return date.format('MMM D, YYYY');
  } catch (error) {
    console.error('Error formatting date for display:', error);
    return dateString;
  }
};

/**
 * Checks if a date is in a given range
 */
export const isDateInRange = (dateString, startDate, endDate) => {
  if (!startDate || !endDate) return false;

  const date = dayjs(dateString);
  const start = dayjs(startDate);
  const end = dayjs(endDate);

  // Check if date is between start and end
  return date.isAfter(start) && date.isBefore(end) || date.isSame(start) || date.isSame(end);
};

/**
 * Navigate to the previous month
 */
export const getPreviousMonth = (currentYear, currentMonth) => {
  if (currentMonth === 0) {
    return { year: currentYear - 1, month: 11 };
  } else {
    return { year: currentYear, month: currentMonth - 1 };
  }
};

/**
 * Navigate to the next month
 */
export const getNextMonth = (currentYear, currentMonth) => {
  if (currentMonth === 11) {
    return { year: currentYear + 1, month: 0 };
  } else {
    return { year: currentYear, month: currentMonth + 1 };
  }
};
